class ClaudeCodeProviderAdapter(BaseProviderAdapter):
    """Own Claude Code print/stream-JSON flags and record shapes."""

    provider_id = "claude-code"

    def build_argv(self, spec: ProviderLaunchSpec) -> list[str]:
        if spec.action not in {"start", "resume"}:
            raise ProviderAdapterError("Claude Code action must be start or resume")
        # Claude Code has no -c config channel: config_overrides and
        # env_overrides travel as child-process env entries merged by the
        # controller.  Running the translation here validates every entry
        # (fail loud) so a spec-level drop is impossible even on the
        # standalone adapter contract path.
        claude_child_env_overrides(spec)
        # The real Claude CLI hard-rejects --print + stream-json without
        # --verbose (exit 1: "requires --verbose"), so it is always emitted
        # in print/stream-json mode.
        argv = [*spec.command, "--print", "--output-format", "stream-json", "--verbose"]
        if spec.action == "resume":
            if not spec.session_id:
                raise ProviderAdapterError("Claude Code resume requires a session ID")
            argv.extend(["--resume", spec.session_id])
        if spec.model:
            argv.extend(["--model", spec.model])
        # Default bypass (mirrors Codex): without a permission mode the CLI
        # defaults to interactive prompting, so a caller following the
        # documented shapes gets a lane that silently does nothing (every
        # tool blocked, yet EXIT 0).  An explicit caller value still wins.
        permission_mode = spec.permission_mode or "bypassPermissions"
        argv.extend(["--permission-mode", permission_mode])
        for tool in spec.allowed_tools:
            argv.extend(["--allowedTools", tool])
        for tool in spec.disallowed_tools:
            argv.extend(["--disallowedTools", tool])
        if spec.mcp_config:
            mcp_value = (
                spec.mcp_config
                if isinstance(spec.mcp_config, str)
                else json.dumps(spec.mcp_config, sort_keys=True, separators=(",", ":"))
            )
            argv.extend(["--mcp-config", mcp_value])
        return argv

    def encode_prompt(self, prompt: bytes) -> bytes:
        if not isinstance(prompt, bytes) or not prompt:
            raise ProviderAdapterError("Claude Code prompt must be non-empty bytes")
        return prompt

    def parse_transcript_line(self, line: bytes) -> ProviderEvent | None:
        value = _json_line(line)
        if value is None:
            return None
        raw_type = _nonempty(value.get("type"))
        session_id = _nonempty(value.get("session_id")) or _nonempty(
            value.get("sessionId")
        )
        if raw_type == "system":
            subtype = _nonempty(value.get("subtype"))
            if subtype == "init":
                return ProviderEvent(
                    "STARTED", session_id=session_id, raw_type=raw_type
                )
            if subtype == "permission_denied":
                # A tool was blocked (Write etc.).  The turn still ends
                # is_error:false/subtype:success with EXIT 0, so this line is
                # the only in-stream signal that the work never happened.  It
                # is emitted as FAILED (never COMPLETED); the terminal result
                # line below additionally carries its own permission_denials
                # list so the final classification stays FAILED even though
                # this earlier event is later overwritten.
                detail = _nonempty(value.get("message"))
                if detail is None:
                    tool = _nonempty(value.get("tool_name"))
                    detail = f"permission_denied {tool}".strip() or subtype
                return ProviderEvent(
                    "FAILED",
                    session_id=session_id,
                    outcome="FAILED",
                    raw_type=raw_type,
                    detail=detail,
                )
            return None
        if raw_type != "result":
            return None
        subtype = _nonempty(value.get("subtype"))
        permission_denials = value.get("permission_denials")
        denied = isinstance(permission_denials, list) and bool(permission_denials)
        is_error = value.get("is_error") is True or subtype in {
            "error",
            "error_during_execution",
        }
        if is_error or denied:
            detail = _nonempty(value.get("result")) or subtype
            if denied:
                tools = ",".join(
                    str(item.get("tool_name"))
                    for item in permission_denials
                    if isinstance(item, Mapping) and _nonempty(item.get("tool_name"))
                )
                detail = f"permission_denied {tools}".strip() or detail
            return ProviderEvent(
                "FAILED",
                session_id=session_id,
                outcome="FAILED",
                raw_type=raw_type,
                detail=detail,
            )
        return ProviderEvent(
            "COMPLETED", session_id=session_id, outcome="COMPLETED", raw_type=raw_type
        )

    def terminal_outcome(self, event: ProviderEvent | None, exit_code: int) -> str:
        if event is not None and event.kind in {"FAILED", "CANCELLED"}:
            return event.kind
        return "COMPLETED" if exit_code == 0 else "FAILED"

    def notification_wake_text(self) -> str | None:
        # Claude Code has no immediate in-turn wake boundary; drain is
        # SAFE_BOUNDARY_ONLY and is never fabricated as an immediate wake.
        return None

    def redact_argv(self, argv: list[str] | tuple[str, ...]) -> tuple[str, ...]:
        # Claude Code command provenance uses the deterministic generic
        # markers; the adapter owns the operation so foreign spellings stay
        # adapter-bound.
        return redact_command(argv)


