CLAUDE_CONFIG_OVERRIDE_ALIASES: Mapping[str, Mapping[str, str]] = {
    'model_provider="ollama"': {
        "ANTHROPIC_BASE_URL": "http://localhost:11434",
        "ANTHROPIC_AUTH_TOKEN": "ollama",
        "ANTHROPIC_API_KEY": "",
    },
}


def claude_config_override_env(override: str) -> Mapping[str, str]:
    """Translate one claude-code ``config_overrides`` entry into env assignments.

    Two shapes are accepted; anything else raises ``ProviderAdapterError`` so
    an override is never silently dropped:

    * the exact ``model_provider="ollama"`` alias, which expands to the three
      Ollama redirect variables, or
    * an explicit ``ANTHROPIC_*`` env assignment (``ANTHROPIC_BASE_URL=...``,
      ``ANTHROPIC_API_KEY=``); a single layer of surrounding double quotes is
      stripped so the Codex ``-c`` quoting convention works verbatim.
    """
    alias = CLAUDE_CONFIG_OVERRIDE_ALIASES.get(override)
    if alias is not None:
        return dict(alias)
    key, sep, value = override.partition("=")
    key = key.strip()
    if (
        not sep
        or not key.startswith("ANTHROPIC_")
        or not key.isidentifier()
    ):
        raise ProviderAdapterError(
            "claude-code config_overrides entries must be the "
            'model_provider="ollama" alias or an ANTHROPIC_* env assignment '
            f"(got {override!r}); Claude Code has no -c config channel"
        )
    if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
        value = value[1:-1]
    return {key: value}


def claude_child_env_overrides(spec: ProviderLaunchSpec) -> Mapping[str, str]:
    """The declared ANTHROPIC_* child-environment channel for claude-code.

    ``spec.config_overrides`` entries are translated (the
    ``model_provider="ollama"`` alias expands to the three Ollama redirect
    variables; explicit ``ANTHROPIC_*`` entries pass verbatim) and explicit
    ``spec.env_overrides`` entries are validated and merged.  Any other entry
    raises ``ProviderAdapterError`` so an override is never silently dropped.
    """
    merged: dict[str, str] = {}
    for override in spec.config_overrides:
        merged.update(claude_config_override_env(override))
    for key, value in spec.env_overrides.items():
        if (
            not isinstance(key, str)
            or not key.startswith("ANTHROPIC_")
            or not key.isidentifier()
        ):
            raise ProviderAdapterError(
                "claude-code env override keys must be ANTHROPIC_* env vars "
                f"(got {key!r})"
            )
        if not isinstance(value, str):
            raise ProviderAdapterError(
                f"claude-code env override {key!r} must have a string value"
            )
        merged[key] = value
    return merged


class CodexProviderAdapter(BaseProviderAdapter):
    """Own the current Codex command and transcript shapes."""

    provider_id = "codex"

    def build_argv(self, spec: ProviderLaunchSpec) -> list[str]:
        if spec.action not in {"start", "resume"}:
            raise ProviderAdapterError("Codex action must be start or resume")
        argv = [*spec.command, "exec"]
        if spec.action == "resume":
            if not spec.session_id:
                raise ProviderAdapterError("Codex resume requires a session ID")
            argv.extend(["resume", spec.session_id])
        argv.append("--dangerously-bypass-approvals-and-sandbox")
        argv.extend(
            [
                "--ignore-user-config",
                "--skip-git-repo-check",
                "-c",
                f'approval_policy="{spec.approval_policy}"',
                "-m",
                spec.model,
                "-c",
                f'model_reasoning_effort="{spec.reasoning_effort}"',
                "-c",
                f'service_tier="{spec.service_tier}"',
            ]
        )
        if spec.worker_invocation_id is None:
            argv.extend(["-c", 'approvals_reviewer="user"'])
        for override in spec.config_overrides:
            argv.extend(["-c", override])
        argv.extend(["--json", "--output-last-message", str(spec.last_message_path)])
        if spec.action == "start":
            argv.extend(["--cd", str(spec.run_root)])
        argv.append("-")
        return argv

    def encode_prompt(self, prompt: bytes) -> bytes:
        if not isinstance(prompt, bytes) or not prompt:
            raise ProviderAdapterError("Codex prompt must be non-empty bytes")
        return prompt

    def parse_transcript_line(self, line: bytes) -> ProviderEvent | None:
        value = _json_line(line)
        if value is None:
            return None
        raw_type = _nonempty(value.get("type"))
        if raw_type != "thread.started" and raw_type not in {
            "turn.completed",
            "turn.failed",
            "turn.cancelled",
        }:
            return None
        session_id = _nonempty(value.get("thread_id")) or _nonempty(
            value.get("threadId")
        )
        if raw_type == "thread.started":
            return ProviderEvent("STARTED", session_id=session_id, raw_type=raw_type)
        kind = {
            "turn.completed": "COMPLETED",
            "turn.failed": "FAILED",
            "turn.cancelled": "CANCELLED",
        }[raw_type]
        return ProviderEvent(
            kind, session_id=session_id, outcome=kind, raw_type=raw_type
        )

